class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final row and column to position
        return row * n + col

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # dp[j] = number of ways to assign arr1 such that last element is j
        dp = [0] * (nums[0] + 1)
        for j in range(nums[0] + 1):
            dp[j] = 1

        # Process each position from 1 to n-1
        for i in range(1, n):
            new_dp = [0] * (nums[i] + 1)

            # For each possible value of arr1[i-1]
            for prev_val in range(len(dp)):
                if dp[prev_val] == 0:
                    continue

                # For each possible value of arr1[i]
                for curr_val in range(nums[i] + 1):
                    # arr1 must be non-decreasing: curr_val >= prev_val
                    if curr_val < prev_val:
                        continue

                    # arr2 must be non-increasing: 
                    # nums[i-1] - prev_val >= nums[i] - curr_val
                    # This gives: curr_val >= prev_val + (nums[i-1] - nums[i])
                    min_curr_val = prev_val + max(0, nums[i-1] - nums[i])

                    if curr_val >= min_curr_val:
                        new_dp[curr_val] = (new_dp[curr_val] + dp[prev_val]) % MOD

            dp = new_dp

        # Sum all valid final configurations
        return sum(dp) % MOD

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store count of each color for each player
        player_color_count = {}

        # Initialize for all players
        for i in range(n):
            player_color_count[i] = {}

        # Count balls for each player and color
        for player, color in pick:
            if color not in player_color_count[player]:
                player_color_count[player][color] = 0
            player_color_count[player][color] += 1

        # Count how many players win
        win_count = 0

        # Check each player from 0 to n-1
        for player in range(n):
            # Find the maximum count of any single color this player picked
            max_count = 0
            for color, count in player_color_count[player].items():
                max_count = max(max_count, count)

            # Player i wins if they have more than i balls of the same color
            # (i.e., at least i+1 balls)
            if max_count > player:
                win_count += 1

        return win_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed for all rows to be palindromic
        row_flips = 0
        for i in range(m):
            for j in range(n // 2):
                # Compare symmetric positions in row i
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Calculate flips needed for all columns to be palindromic
        col_flips = 0
        for j in range(n):
            for i in range(m // 2):
                # Compare symmetric positions in column j
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        # Return the minimum of the two options
        return min(row_flips, col_flips)

